+// Retry helper for operations that might fail due to timeout
+async function queryWithRetry(sql, values, maxRetries = 3) {
+  let lastErr;
+  for (let attempt = 0; attempt < maxRetries; attempt++) {
+    try {
+      return await pool.query(sql, values);
+    } catch (err) {
+      lastErr = err;
+      if (attempt < maxRetries - 1 && err.message.includes('timeout')) {
+        // Wait before retry, with exponential backoff
+        await new Promise(r => setTimeout(r, Math.min(100 * Math.pow(2, attempt), 1000)));
+      } else {
+        throw err;
+      }
+    }
+  }
+  throw lastErr;
